source("pre.R")
P <- function(label, expr) { cat("---", label, ": "); r <- tryCatch(expr, error = function(e) cat("ERROR<", class(e)[1], ">:", conditionMessage(e), "\n")); if (!is.null(r)) { if (is.character(r)) cat(r, sep = "\n") else try_(print(r)) }; invisible(r) }
P("peek compact detached", { p <- jose_peek(jws_sign("hello", key, "HS256", detached = TRUE)); list(payload = p$payload, si_null = is.null(p$signing_input[[1]])) })
P("peek flattened detached", { p <- jose_peek(jws_sign("hello", key, "HS256", detached = TRUE, format = "flattened")); list(payload = p$payload, si_null = is.null(p$signing_input[[1]])) })
cat("=== kid selection\n")
kl <- jwk_oct(as.raw(1:32), kid = iconv("clé", "UTF-8", "latin1")); ku <- jwk_oct(as.raw(1:32), kid = "clé")
t <- jws_sign("x", kl, "HS256"); cat(header_of(t), "\n")
P("latin1 kid key in set vs utf8 header", jws_verify(t, jwk_set(kl), "HS256")$kid)
P("set [[ latin1", jwk_set(kl)[["clé"]]$kty); P("set [[ utf8 key, latin1 index", jwk_set(ku)[[iconv("clé", "UTF-8", "latin1")]]$kty)
P("thumbprint same", identical(jwk_thumbprint(kl), jwk_thumbprint(ku)))
P("json same", identical(jwk_json(kl, TRUE), jwk_json(ku, TRUE)))
s <- jwk_set(jwk_oct(as.raw(1:32), kid = "a"), jwk_oct(as.raw(2:33), kid = "ab"), jwk_oct(as.raw(3:34)))
P("token no kid, set tries all", { t <- jws_sign("x", jwk_oct(as.raw(3:34)), "HS256"); v <- jws_verify(t, s, "HS256"); is.null(v$kid) })
P("token kid 'ab' → right key", { t <- jws_sign("x", s[["ab"]], "HS256"); jws_verify(t, s, "HS256")$kid })
P("token kid unknown", { t <- jws_sign("x", jwk_oct(as.raw(3:34), kid = "zz"), "HS256"); jws_verify(t, s, "HS256") })
P("token kid '' vs key no kid", { t <- jws_sign("x", jwk_oct(as.raw(3:34), kid = ""), "HS256"); jws_verify(t, s, "HS256") })
P("single key, token kid differs", { t <- jws_sign("x", jwk_oct(as.raw(1:32), kid = "other"), "HS256"); v <- jws_verify(t, s[["a"]], "HS256"); c(v$kid, v$header$kid) })
P("kid in unprotected header selects", { t <- jws_sign("x", s[["ab"]], "HS256", format = "flattened", unprotected = list(kid = "ab")); jws_verify(t, s, "HS256")$kid })
P("resolver gets header; returns set", { t <- jws_sign("x", s[["ab"]], "HS256", header = list(iss = "me")); jws_verify(t, function(h) { cat("[", paste(names(h), collapse = ","), "]"); s }, "HS256")$kid })
P("resolver returns string", jws_verify(jws_sign("x", key, "HS256"), function(h) "k", "HS256"))
P("resolver errors", jws_verify(jws_sign("x", key, "HS256"), function(h) stop("boom"), "HS256"))
P("resolver not called when alg refused", { n <- 0; tryCatch(jws_verify(jws_sign("x", key, "HS256"), function(h) { n <<- n + 1; key }, "HS512"), error = function(e) NULL); n })
P("key use sig for verify; enc refused", jws_verify(jws_sign("x", key, "HS256"), jwk_oct(as.raw(1:32), use = "enc"), "HS256"))
P("key_ops sign only: verify refused", jws_verify(jws_sign("x", key, "HS256"), jwk_oct(as.raw(1:32), key_ops = "sign"), "HS256"))
P("key alg HS512 verifying HS256 token", jws_verify(jws_sign("x", key, "HS256"), jwk_oct(as.raw(1:64), alg = "HS512"), c("HS256", "HS512")))
cat("=== asymmetric sign/verify, two routes\n")
rsa <- jwk_generate("RSA", kid = "r"); ec <- jwk_generate("EC", crv = "P-384", kid = "e")
for (a in c("RS256", "RS384", "RS512", "PS256", "PS384", "PS512")) { t <- jws_sign("x", rsa, a); cat(a, inherits(jws_verify(t, jwk_public(rsa), a), "jws_verified"), inherits(jws_verify(t, as_jwk(jwk_pem(rsa)), a), "jws_verified"), "\n") }
P("ES384", { t <- jws_sign("x", ec, "ES384"); c(class(jws_verify(t, jwk_public(ec), "ES384"))[1], length(zuutf::base64_decode(parts(t)[3], url = TRUE, forgiving = FALSE, pad = FALSE))) })
P("ES256 w/ P-384", jws_sign("x", ec, "ES256"))
P("sign with public RSA", jws_sign("x", jwk_public(rsa), "RS256"))
P("sign with public EC", jws_sign("x", jwk_public(ec), "ES384"))
P("RS256 token verified as HS256 with public key bytes (confusion)", { t <- jws_sign("x", rsa, "RS256"); jws_verify(t, jwk_public(rsa), "HS256") })
P("jwt with RSA", { t <- jwt_encode(list(sub = "u"), rsa, "PS256", expires_in = 60); cl <- jwt_decode(t, jwk_set(jwk_public(rsa), key), "PS256"); print(cl); 1 })
cat("=== print\n")
P("print claims header kidx (partial)", { t <- jws_sign('{"exp":9999999999}', jwk_oct(as.raw(1:32)), "HS256", header = list(typ = "JWT", kidnap = "zzz")); print(jwt_decode(t, key, "HS256")); 1 })
P("print verified header kidx", { t <- jws_sign('x', jwk_oct(as.raw(1:32)), "HS256", header = list(kidnap = "zzz")); print(jws_verify(t, key, "HS256")); 1 })
P("print claims empty", print(jwt_decode(jws_sign('{}', key, "HS256"), key, "HS256", required = character())))
P("print claims odd", print(jwt_decode(jws_sign('{"exp":9999999999,"":1,"a\\nb":"x\\u001b[31m","o":{"a":[1,2,{"b":null}]},"long":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}', key, "HS256"), key, "HS256")))
P("print claims exp huge", print(jwt_decode(jws_sign('{"exp":1e300, "iat": -1e15, "nbf": 0.5}', key, "HS256"), key, "HS256")))
P("claims $ / [[ / as.list / names", { cl <- jwt_decode(jws_sign('{"exp":9999999999,"sub":"u"}', key, "HS256"), key, "HS256"); list(cl$sub, cl[["exp"]], names(cl), class(cl["sub"]), length(cl)) })
P("limits print Inf", print(jose_limits(token = Inf, p2c = 2^40)))
P("error fields", { e <- tryCatch(jwt_decode(jws_sign('{"exp":5.5}', key, "HS256"), key, "HS256", now = as.POSIXct("2026-01-01", tz = "Asia/Tokyo")), error = function(e) e); str(unclass(e)[c("claim", "time", "now")]) })
P("aud error fields", { e <- tryCatch(jwt_decode(jws_sign('{"exp":9999999999,"aud":"x"}', key, "HS256"), key, "HS256", audience = "y"), error = function(e) e); e$claim })
P("validate error claim", { e <- tryCatch(jwt_decode(jws_sign('{"exp":9999999999}', key, "HS256"), key, "HS256", validate = function(x) FALSE), error = function(e) e); e$claim })
cat("=== jwt_encode with signers list / other keys\n")
P("jwt_encode signer list", jwt_encode(list(a = 1), list(jws_signer(key, "HS256"))))
P("jwt_encode key alg default", header_of(jwt_encode(list(a = 1), jwk_oct(as.raw(1:32), alg = "HS256"))))
P("jwt_encode header b64", jwt_encode(list(a = 1), key, "HS256", header = list(b64 = FALSE)))
P("exp: POSIXct with class extra", payload_of(jwt_encode(list(exp = structure(1.9e9, class = c("POSIXct", "POSIXt")), nbf = structure(100.9, class = c("myct", "POSIXct", "POSIXt"))), key, "HS256", issued_at = FALSE)))
P("exp: named numeric", payload_of(jwt_encode(list(exp = c(t = 1.9e9)), key, "HS256", issued_at = FALSE)))
P("exp: difftime", payload_of(jwt_encode(list(exp = as.difftime(1, units = "hours")), key, "HS256", issued_at = FALSE)))
P("exp: integer64-ish big int", payload_of(jwt_encode(list(exp = .Machine$integer.max), key, "HS256", issued_at = FALSE)))
P("exp neg frac posix", payload_of(jwt_encode(list(exp = as.POSIXct(-0.5, origin = "1970-01-01")), key, "HS256", issued_at = FALSE)))
P("expires_in difftime days", { p <- zujson::json_parse(payload_of(jwt_encode(list(), key, "HS256", expires_in = as.difftime(1, units = "days")))); p$exp - p$iat })
P("expires_in difftime weeks 'auto'", { p <- zujson::json_parse(payload_of(jwt_encode(list(), key, "HS256", expires_in = Sys.time() + 90 - Sys.time()))); p$exp - p$iat })
P("expires_in 2.5 / 3.5 rounding", { f <- function(x) { p <- zujson::json_parse(payload_of(jwt_encode(list(), key, "HS256", expires_in = x))); p$exp - p$iat }; c(f(0.5), f(1.5), f(2.5), f(3.5)) })
P("expires_in 2^31", { p <- zujson::json_parse(payload_of(jwt_encode(list(), key, "HS256", expires_in = 2^31))); p$exp - p$iat })
P("expires_in 1e18", payload_of(jwt_encode(list(), key, "HS256", expires_in = 1e18, issued_at = FALSE)))
P("claims iat given + issued_at", payload_of(jwt_encode(list(iat = 5), key, "HS256")))
P("claims order", payload_of(jwt_encode(list(z = 1, exp = 5, a = 2), key, "HS256", expires_in = 10, not_before = 0, jti = TRUE)))
